W1_WORDING = (
    'The empirical Mapping-F implementation evaluates the attained bundle '
    'against the universally available non-employment reference. Under the '
    'current specification, estimated opportunity density therefore affects '
    'this money metric through attained outcomes rather than through a direct '
    'opportunity-prospect term.')
WEA_STATUS = r'''$W_{EA,\mathrm{flat}}$ is a distinct ex-ante opportunity-prospect metric. Its definition is fixed but it has no numerical result. Write its eventual flat-reference inversion as $H_i^{\mathrm{reference}}(m)=J_i^{\mathrm{actual}}$. The primary H-F domain retains the full opportunity environment: states with $C\leq0$ contribute zero to $J_i^{\mathrm{actual}}$ through the $C\rightarrow0^+$ utility limit, while the reference retains those states and assigns the common consumption $m$. H-D is an estimated-domain sensitivity and H-X is a disclosed sample-restriction sensitivity. No one-euro floor, observed-consumption substitution or silent household deletion is permitted. The 260 couples lacking a priced NN state and the associated support/pricing requirements currently block numerical implementation; the first post-seminar numerical task is exact-H pre-validation before any minimum accepted pricing design is launched.'''


def replace_paragraph(text, prefix, replacement):
    paragraphs = text.split('\n\n')
    hits = [i for i, paragraph in enumerate(paragraphs)
            if paragraph.lstrip().startswith(prefix)]
    if len(hits) != 1:
        raise RuntimeError('Expected one paragraph starting with: ' + prefix)
    paragraphs[hits[0]] = replacement
    return '\n\n'.join(paragraphs)


def clean_w1(text):
    text = text.replace('equivalent flat consumption level',
                        'equivalent consumption at the non-employment reference state')
    text = text.replace(
        'Their references fix a wage or an unearned-income intercept and maximize '
        'over a deterministic budget set. Ours fixes consumption across the '
        'alternatives of an estimated opportunity distribution and integrates. '
        'That is a different reference and, as Section 6 records, the ordering is '
        'sensitive to it.',
        'Their references fix a wage or an unearned-income intercept and maximize '
        'over a deterministic budget set. ' + W1_WORDING)
    return text


def attach_decomp_caveat(text):
    pattern = (r'(Within that bounded game, equalising P/A/B changes the Gini by '
               r'.*?depending on sample and reporting scale\.)')
    text, count = re.subn(pattern, r'\1\n\n' + DECOMP_CAVEAT, text, count=1)
    if count != 1:
        raise RuntimeError('Could not attach the required DECOMP-2 caveat')
    return text


ABSTRACT = r'''We study how unequal job opportunities contribute to inequality in money-metric well-being. The verified current measure is the Mapping-F attained-bundle money metric: the attained bundle is evaluated against the universally available non-employment reference, so estimated opportunity density affects the measure through attained outcomes rather than through a direct opportunity-prospect term. We model labour supply as a choice among latent jobs on French EU-SILC data, with EUROMOD computing taxes, benefits and disposable income at every alternative work arrangement. Preferences and opportunity components are jointly estimated under maintained functional-form and exclusion restrictions. We implement a preliminary restricted structural decomposition of the attained-bundle money metric, equalising systematic utility heterogeneity, coarse geographic/temporal access heterogeneity and earning opportunities while holding household resources, needs and composition fixed. Within this restricted game, the earning-opportunity channel has a larger Shapley contribution than the coarse geographic/temporal access channel. The exercise is preliminary and is not interpreted as the total share of well-being inequality due to opportunities.'''

PRELIM_NOTE = (
    'Discussion draft. Corrected POSFIT-v3b predictive evidence and the verified '
    'Mapping-F results are reported with the preliminary restricted P/A/B '
    'decomposition in the main text; Appendix D retains its full technical record. '
    'The distinct ex-ante opportunity-prospect metric is defined but numerically blocked.')

INTRO = clean_w1(v6.INTRO)
